INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Datenbanksystem dasselbe wie eine Datenbank?', 2, '[{"text": "Nein", "correct": true, "because": "System umfasst DBMS und Datenbank"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Datenbanksystem?', 3, '[{"text": "Daten strukturiert verwalten", "correct": true, "because": "Effiziente Speicherung und Zugriff"}, {"text": "Hardware reparieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Software entwickeln", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem Datenbanksystem?', 5, '[{"text": "Datenbank", "correct": true, "because": "Speichert Daten"}, {"text": "DBMS", "correct": true, "because": "Verwaltet Daten"}, {"text": "Grafiktreiber", "correct": false, "because": "Kein Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Datenbanksystem organisiert Daten. b) Es ist immer Cloud-basiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch lokal möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung eines Datenbanksystems?', 4, '[{"text": "Sicherheit", "correct": false, "because": "Schützt Daten"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Wachstum"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jedes Datenbanksystem relationale Daten nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch NoSQL-Systeme existieren"}, {"text": "Ja", "correct": false, "because": "Verschiedene Typen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Datenbanksystem ist für Tabellen typisch?', 3, '[{"text": "MySQL", "correct": true, "because": "Relationales System"}, {"text": "Cassandra", "correct": false, "because": "NoSQL-System"}, {"text": "Apache", "correct": false, "because": "Webserver"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Datenbanksystem?', 5, '[{"text": "Datenkonsistenz", "correct": true, "because": "Sichert Integrität"}, {"text": "Effizienter Zugriff", "correct": true, "because": "Schnelle Abfragen"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Hardware-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Datenbanksystem verwaltet Daten. b) Es ist immer kostenpflichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Datenbanksystem?', 4, '[{"text": "Datenbanksoftware", "correct": false, "because": "Verwaltung nötig"}, {"text": "Speichermedium", "correct": false, "because": "Datenablage erforderlich"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Datenbanksystem immer lokal?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Cloud-basiert möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen von Datenbanksystemen gibt es?', 4, '[{"text": "Relational", "correct": true, "because": "Tabellenbasiert"}, {"text": "NoSQL", "correct": true, "because": "Flexible Struktur"}, {"text": "Grafisch", "correct": false, "because": "Kein Datentyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Datenbanksystem keine Sicherheit braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schutz essenziell"}, {"text": "Ja", "correct": false, "because": "Sicherheit erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Datenbanksystem?', 3, '[{"text": "Zuverlässigkeit", "correct": true, "because": "Sichert Datenverfügbarkeit"}, {"text": "Minimale Kosten", "correct": false, "because": "Qualität wichtiger"}, {"text": "Schnelle Installation", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenbanksysteme unterstützen SQL. b) Sie sind immer Open Source.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht alle sind Open Source"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt ein Datenbanksystem?', 5, '[{"text": "Daten speichern", "correct": true, "because": "Grundfunktion"}, {"text": "Daten abfragen", "correct": true, "because": "Zugriff ermöglichen"}, {"text": "Hardware warten", "correct": false, "because": "Kein Hardware-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verwaltung unwichtig?', 3, '[{"text": "Backup", "correct": false, "because": "Schützt vor Verlust"}, {"text": "Zugriffskontrolle", "correct": false, "because": "Sichert Daten"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht ein Datenbanksystem immer eine GUI?', 3, '[{"text": "Nein", "correct": true, "because": "Auch CLI möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenbanksysteme nur für Firmen sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch privat nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das DBMS im System?', 4, '[{"text": "Verwaltung", "correct": true, "because": "Steuert Datenbankzugriff"}, {"text": "Grafikverarbeitung", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Netzwerksteuerung", "correct": false, "because": "Anderer Bereich"}]');
